import { loadSharedConfigFiles } from "@smithy/core/dist-es/submodules/config/shared-ini-file-loader/loadSharedConfigFiles";
import { mergeConfigFiles } from "@smithy/core/dist-es/submodules/config/shared-ini-file-loader/mergeConfigFiles";
export const parseKnownFiles = async (init) => {
    const parsedFiles = await loadSharedConfigFiles(init);
    return mergeConfigFiles(parsedFiles.configFile, parsedFiles.credentialsFile);
};
